// Les articles de départ, dans le même ordre que les réponses de l'IA
const articles = $('Liste des articles').all();

const normaliserSource = s =>
  /bkgr|bmce/i.test(s ?? '') ? 'BMCE Capital Global Research' : (s ?? 'Inconnue');

// Liste fermée des périmètres acceptés pour une année donnée
const PERIMETRES = ['Scope 40', 'marché total', 'hors valeurs minières'];

// Normalise le libellé d'une moyenne, ou renvoie null s'il est inconnu
function normaliserMoyenne(libelle) {
  if (/r[ée]cente/i.test(libelle)) return 'moyenne récente (période non précisée)';
  const m = libelle.match(/(\d+)\s*ans/i);
  return m ? `moyenne historique ${m[1]} ans` : null;
}

const sorties = [];

$input.all().forEach((item, i) => {
  const article = articles[i].json;
  const nettoye = item.json.text.replace(/```json|```/g, '').trim();

  let donnees;
  try {
    donnees = JSON.parse(nettoye);
  } catch (e) {
    throw new Error(`Réponse JSON illisible pour ${article.url}`);
  }
  if (!donnees.valorisations || donnees.valorisations.length === 0) {
    throw new Error(`Aucune valorisation trouvée pour ${article.url}`);
  }

  for (const v of donnees.valorisations) {
    // Règle 1 : une ligne sans aucun chiffre ne sert à rien
    if (v.per === null && v.rendement_dividende_pct === null) continue;

    let perimetre = v.perimetre;
    let estimation = v.estimation;

    if (v.annee === null) {
      // Règle 2 : une moyenne a un libellé standard et n'est jamais une prévision
      perimetre = normaliserMoyenne(perimetre);
      estimation = false;
      if (!perimetre) {
        throw new Error(`Libellé de moyenne inconnu « ${v.perimetre} » pour ${article.url}`);
      }
    } else if (!PERIMETRES.includes(perimetre)) {
      // Règle 3 : un périmètre hors de la liste fermée arrête le workflow
      throw new Error(`Périmètre inconnu « ${perimetre} » pour ${article.url}`);
    }

    sorties.push({
      json: {
        annee: v.annee,
        perimetre: perimetre,
        per: v.per,
        rendement_dividende_pct: v.rendement_dividende_pct,
        estimation: estimation,
        source: normaliserSource(v.source),
        url_article: article.url,
        date_article: article.date_article
      }
    });
  }
});

return sorties;

return [
  { json: { url: 'https://boursenews.ma/article/marches/entreprises-cotees-bkgr-publie-ses-previsions-2024-2025', date_article: '2024-05-15' } },
  { json: { url: 'https://boursenews.ma/article/marches/societes-cotees-bkgr-anticipation-capacite-beneficiaire-2024', date_article: '2024-10-22' } },
  { json: { url: 'https://boursenews.ma/article/marches/CFG-bank-devoile-previsions-2025', date_article: '2025-01-29' } },
  { json: { url: 'https://boursenews.ma/article/marches/bourse-cfg-bank-devoile-ses-previsions-2026-et-huit-actions-conseillees', date_article: '2026-02-09' } }
];

